mapper.select:
select * from ( select sm.*, m.machine_code, m.machine_name from T_GSQ_TWINING_DISC sm left join T_GSQ_MACHINE_INFO m on sm.machine_id = m.id where sm.DEL_FLAG = 0 and m.DEL_FLAG = 0
and INSTR(SERIAL_NUMBER, #{serialNumber}) > 0
and INSTR(order_way, #{orderWay}) > 0
AND instr(name, #{name} )>0
AND MACHINE_ID = #{machineId}
order by sm.create_time desc
) t
order by ${orderStr}

mapper.update:
update t_gsq_twining_disc
serial_number = #{serialNumber}, name = #{name}, seq = #{seq}, purpose = #{purpose}, spec = #{spec}, order_way = #{orderWay}, twining_num = #{twiningNum,jdbcType=DECIMAL}, in_time = #{inTime,jdbcType=DATE}, scrap_time = #{scrapTime,jdbcType=DATE}, scrap_reason = #{scrapReason}, machine_id = #{machineId}, del_flag = #{delFlag}, remark = #{remark}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime},
where id = #{id}
